targets.query:
// STUB (v1): projected-total overlay deferred — see docs/phase-8-comed-bill-ingest-plan.md Task 16.
// Target: for each bill cycle, sum (Refoss whole-home W * ComEd hourly price)
// over [service_from, service_to) and compare against the bill total above.
// Implementation needs a join between the bill cycles and the energy/price
// streams; non-trivial Flux deferred until ~3+ cycles of data accumulate.
from(bucket: "energy")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "comed.bill" and r._field == "total_due")
  |> map(fn: (r) => ({ r with _value: 0.0 }))
  |> keep(columns: ["_time", "_value"])
  |> yield(name: "Projected (stub)")
